# Setup
import os, re, io
from datetime import datetime, timezone
import pandas as pd

RUN_TS = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")

if not LOCAL_DIRS:
    from notebookutils import mssparkutils
    ACCOUNTS = {"dev": "pinssts62adevukseftlkl", "test": "pinssts62atestuksnkavj4", "prod": "pinssts62aproduksrz8i4g"}
    ws = mssparkutils.env.getWorkspaceName().lower()
    m = re.search(r"(?:^|[-_])(dev|test|prod)(?:[-_]|$)", ws)
    if not m:
        raise ValueError(f"Can't detect env from workspace name '{ws}'")
    ROOT = f"abfss://s62a@{STORAGE_ACCOUNT or ACCOUNTS[m.group(1)]}.dfs.core.windows.net/PIPELINE"
    print("Env:", m.group(1), "| Root:", ROOT)

def path(key):
    return LOCAL_DIRS[key] if LOCAL_DIRS else f"{ROOT}/{FOLDERS[key]}"

def list_csvs(key):
    if LOCAL_DIRS:
        return sorted(f for f in os.listdir(path(key)) if f.lower().endswith(".csv"))
    return sorted(f.name for f in mssparkutils.fs.ls(path(key)) if f.name.lower().endswith(".csv"))

def read(key, name):
    if LOCAL_DIRS:
        text = open(os.path.join(path(key), name), encoding="utf-8").read()
    else:
        local = f"/tmp/subset_{key}_{name}"
        mssparkutils.fs.cp(f"{path(key)}/{name}", f"file:{local}")
        text = open(local, encoding="utf-8").read()
    if not text.strip():
        return pd.DataFrame()
    # keep every value exactly as written (no NaN / float conversion), so untouched columns round-trip
    return pd.read_csv(io.StringIO(text), dtype=str, keep_default_na=False)

def write(key, name, df):
    text = df.to_csv(index=False, encoding="utf-8")
    if LOCAL_DIRS:
        open(os.path.join(path(key), name), "w", encoding="utf-8").write(text)
    else:
        local = f"/tmp/subset_out_{key}_{name}"
        open(local, "w", encoding="utf-8").write(text)
        mssparkutils.fs.cp(f"file:{local}", f"{path(key)}/{name}")

def backup(key):
    dest = f"{BACKUP_ROOT}/{RUN_TS}/{key}"
    if LOCAL_DIRS:
        import shutil
        shutil.copytree(path(key), os.path.join(path(key), "..", f"_backup_{RUN_TS}_{key}"))
        return
    mssparkutils.fs.cp(path(key), f"{ROOT}/{dest}", True)
    print(f"Backed up {FOLDERS[key]} -> {dest}")

# Load everything
data = {key: {name: read(key, name) for name in list_csvs(key)} for key in FOLDERS}
for key, files in data.items():
    print(key, {n: len(df) for n, df in files.items()})

S, D = data["SCHEMA"], data["DOCUMENTS"]
user_file = next((n for n in data["USERS"] if n.lower() == "user.csv"), None)

# Resolve the cases (accepts S62A/2024/0032 or S62A/2024/0000032 or the historical ref)
def to_mpa(ref):
    m = re.match(r"^S62A/(\d{4})/(\d+)(RD)?$", ref.strip(), re.I)
    return f"S62A/{m.group(1)}/{int(m.group(2)):07d}{m.group(3) or ''}" if m else ref.strip()

cases = S["S62aCase.csv"]
wanted = {r.strip() for r in CASE_REFS} | {to_mpa(r) for r in CASE_REFS}
keep_cases = cases[cases["reference"].isin(wanted) | cases["historicalReference"].isin(wanted)]
missing = [r for r in CASE_REFS if not ({r.strip(), to_mpa(r)} & set(keep_cases["reference"]) | {r.strip()} & set(keep_cases["historicalReference"]))]
if missing:
    raise ValueError(f"Not found in S62aCase.csv: {missing}")
CASE_IDS = set(keep_cases["id"])
print(f"Keeping {len(CASE_IDS)} case(s):", keep_cases[["reference", "historicalReference", "id"]].to_dict("records"))

# Follow every link from those cases
def by(df, col, ids):
    return df[df[col].isin(ids)] if len(df) and col in df.columns else df.iloc[0:0]

out = {"SCHEMA": {}, "DOCUMENTS": {}, "USERS": {}}
O = out["SCHEMA"]
O["S62aCase.csv"] = keep_cases
for name in ["S62aDates.csv", "S62aFees.csv", "S62aEvent.csv", "S62aResidential.csv", "S62aNonResidential.csv",
             "S62aCaseInspector.csv", "S62aVehicleParking.csv", "S62aCaseWasteType.csv"]:
    if name in S:
        O[name] = by(S[name], "s62aCaseId", CASE_IDS)
for name in ["S62aToApplicant.csv", "ApplicationNote.csv"]:
    if name in S:
        O[name] = by(S[name], "s62aId", CASE_IDS)
if "S62aResidentialHousing.csv" in S:
    O["S62aResidentialHousing.csv"] = by(S["S62aResidentialHousing.csv"], "s62aResidentialId", set(O["S62aResidential.csv"]["id"]))
if "S62aNonResidentialFloorspace.csv" in S:
    O["S62aNonResidentialFloorspace.csv"] = by(S["S62aNonResidentialFloorspace.csv"], "s62aNonResidentialId", set(O["S62aNonResidential.csv"]["id"]))
if "S62aNonResidentialFloorspaceArea.csv" in S:
    O["S62aNonResidentialFloorspaceArea.csv"] = by(S["S62aNonResidentialFloorspaceArea.csv"], "s62aFloorspaceEntryId",
                                                   set(O["S62aNonResidentialFloorspace.csv"]["id"]))

ta = O["S62aToApplicant.csv"]
contact_ids = set(ta["contactId"]) | set(keep_cases["lpaContactId"]) | set(keep_cases["secondaryLpaContactId"])
O["Contact.csv"] = by(S["Contact.csv"], "id", contact_ids - {""})
O["Organisation.csv"] = by(S["Organisation.csv"], "id", set(ta["organisationId"]) - {""})
address_ids = set(keep_cases["siteAddressId"]) | set(O["Contact.csv"]["addressId"]) | set(O["Organisation.csv"]["addressId"])
O["Address.csv"] = by(S["Address.csv"], "id", address_ids - {""})

# helper files: keep only rows for these cases
for name in ["_exceptions.csv", "_rejected.csv"]:
    if name in S and len(S[name]):
        df = S[name]
        mask = pd.Series(False, index=df.index)
        if "caseId" in df.columns:
            mask |= df["caseId"].isin(CASE_IDS)
        if "caseReference" in df.columns:
            mask |= df["caseReference"].isin(set(keep_cases["reference"]))
        O[name] = df[mask]
if "_load_order.csv" in S:
    lo = S["_load_order.csv"].copy()
    lo["rows"] = lo["table"].map(lambda t: str(len(O.get(f"{t}.csv", pd.DataFrame()))))
    O["_load_order.csv"] = lo

# documents
OD = out["DOCUMENTS"]
if "Folder.csv" in D:
    OD["Folder.csv"] = by(D["Folder.csv"], "s62aCaseId", CASE_IDS)
if "Document.csv" in D:
    OD["Document.csv"] = by(D["Document.csv"], "s62aCaseId", CASE_IDS)
if "_folder_lineage.csv" in D:
    OD["_folder_lineage.csv"] = by(D["_folder_lineage.csv"], "s62aCaseId", CASE_IDS)
for name in ["_document_exceptions.csv", "_document_rejected.csv"]:
    if name in D and len(D[name]) and "caseReference" in D[name].columns:
        OD[name] = D[name][D[name]["caseReference"].isin(set(keep_cases["reference"]))]

# users: only the people these cases point at (+ the note author)
if user_file:
    user_ids = set()
    for col in ["assessorInspectorId", "caseOfficerId", "planningOfficerId", "readerId"]:
        user_ids |= set(keep_cases.get(col, pd.Series(dtype=str)))
    user_ids |= set(O["S62aCaseInspector.csv"].get("userId", pd.Series(dtype=str)))
    user_ids |= set(O["ApplicationNote.csv"].get("userId", pd.Series(dtype=str)))
    out["USERS"][user_file] = by(data["USERS"][user_file], "id", user_ids - {""})

# Write: back up each folder, then replace its files with the cut-down versions
if DRY_RUN:
    print("DRY_RUN = True, nothing written")
else:
    for key, files in out.items():
        if not files:
            continue
        backup(key)
        for name, df in files.items():
            write(key, name, df)
        print(f"Wrote {len(files)} file(s) to {FOLDERS[key]}")
    if not LOCAL_DIRS:
        print(f"\nTo restore the full data, copy {BACKUP_ROOT}/{RUN_TS}/<FOLDER> back over the latest folders "
              f"(or just rerun the notebooks).")
